if (n <= 0) {
    return 0;
}
const uint64_t max = static_cast<uint64_t>(std::numeric_limits<uint32_t>::max()) + 1;
const uint64_t range = static_cast<uint64_t>(n);
uint32_t result;
do {
    result = static_cast<uint32_t>(std::uniform_int_distribution<uint64_t>(0, max - 1)(std::mt19937_64()));
} while (result >= range);
return result;
// END_CODE

